package mz.gov.mogovolas.expedientes.config;
import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.*;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(PermissaoRepository pr,PapelRepository rr,SectorRepository sr,UtilizadorRepository ur,PasswordEncoder enc){return args->{String[][] ps={{"UTILIZADOR_GERIR","Gerir utilizadores"},{"PAPEL_GERIR","Gerir papéis"},{"SECTOR_GERIR","Gerir sectores"},{"EXPEDIENTE_CRIAR","Criar expediente"},{"EXPEDIENTE_EDITAR","Editar expediente"},{"EXPEDIENTE_VISUALIZAR","Visualizar expediente"},{"EXPEDIENTE_TRAMITAR","Tramitar expediente"},{"EXPEDIENTE_RECEBER","Receber expediente"},{"DESPACHO_EMITIR","Emitir despacho"},{"EXPEDIENTE_ARQUIVAR","Arquivar expediente"},{"ANEXO_GERIR","Gerir anexos"},{"AUDITORIA_CONSULTAR","Consultar auditoria"},{"RELATORIO_GERAR","Gerar relatórios"}};Map<String,Permissao> pm=new HashMap<>();for(String[]p:ps)pm.put(p[0],pr.findByCodigo(p[0]).orElseGet(()->pr.save(new Permissao(p[0],p[1]))));Map<String,String[]> map=new LinkedHashMap<>();map.put("ADMIN",Arrays.stream(ps).map(x->x[0]).toArray(String[]::new));map.put("SECRETARIA",new String[]{"EXPEDIENTE_CRIAR","EXPEDIENTE_EDITAR","EXPEDIENTE_VISUALIZAR","EXPEDIENTE_TRAMITAR","EXPEDIENTE_RECEBER","ANEXO_GERIR"});map.put("CHEFE_SECTOR",new String[]{"EXPEDIENTE_VISUALIZAR","EXPEDIENTE_TRAMITAR","EXPEDIENTE_RECEBER","DESPACHO_EMITIR","RELATORIO_GERAR","ANEXO_GERIR"});map.put("SECRETARIO_PERMANENTE",new String[]{"EXPEDIENTE_VISUALIZAR","EXPEDIENTE_TRAMITAR","DESPACHO_EMITIR","RELATORIO_GERAR"});map.put("ARQUIVISTA",new String[]{"EXPEDIENTE_VISUALIZAR","EXPEDIENTE_ARQUIVAR","ANEXO_GERIR"});map.put("AUDITOR",new String[]{"EXPEDIENTE_VISUALIZAR","AUDITORIA_CONSULTAR","RELATORIO_GERAR"});Map<String,Papel> roles=new HashMap<>();for(var e:map.entrySet()){Papel r=rr.findByNome(e.getKey()).orElseGet(()->rr.save(new Papel(e.getKey(),"Perfil "+e.getKey())));for(String x:e.getValue())r.getPermissoes().add(pm.get(x));rr.save(r);roles.put(e.getKey(),r);}Sector s=sr.findByNome("Secretaria Distrital").orElseGet(()->sr.save(new Sector("Secretaria Distrital","Secretaria Distrital de Mogovolas")));for(String n:new String[]{"Administração e Finanças","Educação","Saúde","Planeamento","Arquivo"})sr.findByNome(n).orElseGet(()->sr.save(new Sector(n,"Sector de demonstração")));if(ur.findByUsername("admin").isEmpty()){String initial=System.getenv("ADMIN_PASSWORD");if(initial==null||initial.isBlank()) initial="change-me-now";Utilizador u=new Utilizador();u.setNome("Administrador do Sistema");u.setUsername("admin");u.setEmail("admin@mogovolas.gov.mz");u.setPassword(enc.encode(initial));u.setSector(s);u.getPapeis().add(roles.get("ADMIN"));ur.save(u);}};}}
